#!/usr/bin/env node
// Copies shared/*.json into the two places that need it:
//   ios/Shared/Generated/SharedResources.swift  (compiled into app + widget)
//   preview/generated/shared-data.js            (loaded by the browser preview)
// It also extracts the Swift enum values so the preview's controls offer exactly
// the options the iOS app understands.
//
//   node scripts/sync-shared.mjs          write the generated files
//   node scripts/sync-shared.mjs --check  fail if they are out of date (CI)

import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

export const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const p = (...parts) => join(ROOT, ...parts);

const SOURCES = {
  themes: "shared/themes.json",
  defaults: "shared/defaults.json",
  presets: "shared/presets.json",
};

export const OUTPUTS = {
  swift: "ios/Shared/Generated/SharedResources.swift",
  js: "preview/generated/shared-data.js",
};

export function readJSON(rel) {
  const text = readFileSync(p(rel), "utf8");
  try {
    return JSON.parse(text);
  } catch (err) {
    throw new Error(`${rel}: invalid JSON — ${err.message}`);
  }
}

/** Collects the `case a, b` lines of every top-level `enum Name: String` in Swift source. */
export function parseSwiftEnums(source) {
  const enums = {};
  const re = /^enum\s+(\w+)\s*:\s*String\b[^{]*\{([\s\S]*?)\n\}/gm;
  const caseLine = /^\s*case\s+([A-Za-z_`][\w`]*(?:\s*,\s*[A-Za-z_`][\w`]*)*)\s*$/gm;
  for (const m of source.matchAll(re)) {
    const values = [];
    for (const c of m[2].matchAll(caseLine)) {
      values.push(...c[1].split(",").map((s) => s.trim().replace(/`/g, "")));
    }
    enums[m[1]] = values;
  }
  return enums;
}

function swiftOutput(data) {
  const block = (name, value) => {
    const json = JSON.stringify(value, null, 2);
    if (json.includes('"""#')) throw new Error(`${name} contains a raw-string terminator`);
    return `    static let ${name} = #"""\n${json}\n"""#`;
  };
  return [
    "// GENERATED by scripts/sync-shared.mjs from shared/*.json. Do not edit by hand.",
    "// Run `node scripts/sync-shared.mjs` after changing the JSON files.",
    "",
    "enum SharedResources {",
    block("themesJSON", data.themes),
    "",
    block("defaultsJSON", data.defaults),
    "",
    block("presetsJSON", data.presets),
    "}",
    "",
  ].join("\n");
}

function jsOutput(data, enums) {
  const payload = { themes: data.themes.themes, defaults: data.defaults, presets: data.presets.presets, enums };
  return [
    "// GENERATED by scripts/sync-shared.mjs from shared/*.json and ios/Shared/Models.swift. Do not edit by hand.",
    `window.MARGIN_SHARED = ${JSON.stringify(payload, null, 2)};`,
    "",
  ].join("\n");
}

export function buildOutputs() {
  const data = Object.fromEntries(Object.entries(SOURCES).map(([k, rel]) => [k, readJSON(rel)]));
  const enums = parseSwiftEnums(readFileSync(p("ios/Shared/Models.swift"), "utf8"));
  return { [OUTPUTS.swift]: swiftOutput(data), [OUTPUTS.js]: jsOutput(data, enums) };
}

/** Returns the list of files that changed (or would change with check=true). */
export function sync({ check = false } = {}) {
  const outputs = buildOutputs();
  const changed = [];
  for (const [rel, content] of Object.entries(outputs)) {
    const file = p(rel);
    const current = existsSync(file) ? readFileSync(file, "utf8").replace(/\r\n/g, "\n") : null;
    if (current === content) continue;
    changed.push(rel);
    if (!check) {
      mkdirSync(dirname(file), { recursive: true });
      writeFileSync(file, content, "utf8");
    }
  }
  return changed;
}

if (process.argv[1] && relative(process.argv[1], fileURLToPath(import.meta.url)) === "") {
  const check = process.argv.includes("--check");
  try {
    const changed = sync({ check });
    if (check && changed.length) {
      console.error(`Out of date: ${changed.join(", ")}\nRun: node scripts/sync-shared.mjs`);
      process.exit(1);
    }
    console.log(changed.length ? `Updated ${changed.join(", ")}` : "Generated files are up to date.");
  } catch (err) {
    console.error(err.message);
    process.exit(1);
  }
}
